parameters.jsCode:
// Contexto do lead ANTES do update. Não decide sozinho se notifica —
// quem decide é a trava de janela no Redis (ver nós "Já avisei ...").
// Aqui só preparamos telefone normalizado e o contexto pra mensagem do grupo.

const trigger = $('When Executed by Another Workflow').first().json;
const atual = $('Busca Status Atual').first().json || {};

const norm = (s) => String(s ?? '').trim().toLowerCase();

const statusAnterior = norm(atual.status_anterior);
const statusNovo     = norm(trigger.status_plano_acao);

// telefone só dígitos, com 55 — usado como chave no Redis
const phoneKey = String(trigger.phone ?? '').replace(/\D/g, '');

return [{
  json: {
    ...trigger,
    phone_key: phoneKey,
    status_anterior: atual.status_anterior ?? '',
    mailing_id: atual.mailing_id ?? '',
    ultimo_contato_anterior: atual.ultimo_contato ?? '',
    mudou_status: statusAnterior !== statusNovo,
    // usado só para o texto da mensagem: é a 1a vez ou é retorno de um lead já encaminhado?
    ja_era_advisor:   statusAnterior === 'encaminhar advisor',
    ja_era_parcerias: statusAnterior === 'encaminhar parcerias'
  }
}];

